//! pbrt-v4's unit tests, one module per source file in `src/pbrt/util/`, each
//! test naming the `TEST(Suite, Name)` it ports; and the values pbrt-v4
//! computes on fixed inputs (`known_values.rs`, generated by
//! `known_values.cpp`), checked by the `known_values` tests.
//!
//! Only the sRGB cases are ported: the other colour spaces join when a
//! milestone needs them, `PiecewiseLinearSpectrum` and `BlackbodySpectrum`
//! with `.spd` files and blackbody emitters, and the colour encodings with
//! image textures (arc42 §4.1).

mod color_test;
mod known_values;
mod spectrum_test;

/// Asserts that each of `actual` is within `max_ulps` of the float whose
/// bits are the matching entry of `expected`.
///
/// pbrt-v4's values come from the libm it was built with, Umbra's from its
/// own kernels or glibc (ADR 0022), so a result computed through a
/// transcendental can differ in its last bits; arithmetic alone is compared with `max_ulps` 0.
#[track_caller]
pub(crate) fn assert_ulps<const N: usize>(
    actual: [f32; N],
    expected: [u32; N],
    max_ulps: u32,
    what: &str,
) {
    let distance = actual
        .into_iter()
        .zip(expected.map(f32::from_bits))
        .map(|(a, e)| ulps(a, e))
        .max()
        .unwrap_or(0);
    assert!(
        distance <= max_ulps,
        "{what}: {actual:?} vs pbrt-v4's {:?}, {distance} ulps apart",
        expected.map(f32::from_bits)
    );
}

/// Asserts that each of `actual` is within `tolerance` of the float whose
/// bits are the matching entry of `expected`, relative to the larger of
/// its magnitude and 1.
#[track_caller]
pub(crate) fn assert_close<const N: usize>(
    actual: [f32; N],
    expected: [u32; N],
    tolerance: f32,
    what: &str,
) {
    let expected = expected.map(f32::from_bits);
    let error = actual
        .into_iter()
        .zip(expected)
        .map(|(a, e)| (a - e).abs() / e.abs().max(1.0))
        .fold(0.0, f32::max);
    assert!(
        error <= tolerance,
        "{what}: {actual:?} vs pbrt-v4's {expected:?}, relative error {error}"
    );
}

/// The number of floats between `a` and `b`, with ±0 equal; `u32::MAX`
/// if either is NaN, unless both are.
fn ulps(a: f32, b: f32) -> u32 {
    if a.is_nan() || b.is_nan() {
        return if a.is_nan() && b.is_nan() {
            0
        } else {
            u32::MAX
        };
    }
    let ordered = |f: f32| {
        let bits = i64::from(f.to_bits().cast_signed());
        if bits < 0 {
            i64::from(i32::MIN) - bits
        } else {
            bits
        }
    };
    u32::try_from((ordered(a) - ordered(b)).unsigned_abs()).unwrap_or(u32::MAX)
}

/// The `RGB` whose components are the floats with bits `bits`.
pub(crate) fn rgb(bits: [u32; 3]) -> umbra_spectrum::RGB {
    let [r, g, b] = bits.map(f32::from_bits);
    umbra_spectrum::RGB::new(r, g, b)
}
